with open('index.html','r',encoding='utf-8') as f: html=f.read()
start = html.find('<section id="view-login"')
end = html.find('</section>', start) + len('</section>')
login = '''<section id="view-login" style="position:fixed;inset:0;z-index:999;background:linear-gradient(135deg,#064e3b 0%,#047857 60%,#10b981 100%);display:flex;align-items:center;justify-content:center;padding:24px;"><div style="background:#fff;border-radius:28px;padding:36px 32px;max-width:440px;width:100%;box-shadow:0 30px 60px rgba(6,78,59,.3);text-align:center;position:relative;overflow:hidden;"><div style="position:absolute;top:-60px;right:-60px;width:180px;height:180px;background:radial-gradient(circle,rgba(16,185,129,.15) 0%,transparent 70%);border-radius:50%;"></div><img src="logo.png" alt="Logo" style="width:72px;height:72px;border-radius:50%;object-fit:cover;margin:0 auto 18px;box-shadow:0 10px 25px rgba(6,78,59,.2);display:block;"><h1 style="font-size:24px;font-weight:800;color:#064e3b;letter-spacing:-.03em;margin-bottom:6px;">BHM Recap Apps</h1><p style="color:#64748b;font-size:15px;margin-bottom:28px;">Yayasan Baitussalam Huda Mansurin</p><form onsubmit="event.preventDefault(); doLogin();" style="display:flex;flex-direction:column;gap:14px;text-align:left;"><label style="font-size:13px;font-weight:600;color:#334155;">Username / Nama</label><input type="text" id="name" placeholder="Masukkan username" required style="padding:12px 14px;border-radius:12px;border:1.5px solid #e2e8f0;font-size:15px;background:#f8fafc;transition:.2s;"><label style="font-size:13px;font-weight:600;color:#334155;">Password</label><input type="password" id="pass" placeholder="Masukkan password" required style="padding:12px 14px;border-radius:12px;border:1.5px solid #e2e8f0;font-size:15px;background:#f8fafc;transition:.2s;"><label style="font-size:13px;font-weight:600;color:#334155;">Peran</label><select id="role" style="padding:12px 14px;border-radius:12px;border:1.5px solid #e2e8f0;font-size:15px;background:#fff;cursor:pointer;"><option value="admin">Admin — Full Akses</option><option value="pengurus">Pengurus — Lihat & Download</option></select><button type="submit" style="padding:14px;border-radius:12px;border:none;background:linear-gradient(135deg,#059669,#047857);color:#fff;font-weight:700;font-size:16px;cursor:pointer;box-shadow:0 6px 20px rgba(5,150,105,.35);margin-top:4px;letter-spacing:.02em;">Masuk ke Sistem</button></form><p style="margin-top:18px;font-size:12px;color:#94a3b8;">6 Kelompok Binaan • Baitu Taqwa • Almansurin • Al Huda • Al Malik • Miftahul Jannah • Baitul Makmur</p></div></section>'''
html = html[:start] + login + html[end:]
with open('index.html','w',encoding='utf-8') as f: f.write(html)
print('Login sempurna')
